insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('stress-bucket-pour-off-page', 'Stress Bucket Pour-Off Page', 'worksheet'::resource_kind, 'A bucket drawing where a client marks what fills their stress and what pours some off.', 'Use it to help a client see what is filling their load and pick one release.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client draw a bucket and write what fills it, then name small releases they already use. Keep the focus on one realistic pour-off for the week. Review next session what helped, and let the client decide what stays on the page.', '[{"id": "f0", "type": "textarea", "label": "What is in my bucket right now:"}, {"id": "f1", "type": "textarea", "label": "What fills it fastest:"}, {"id": "f2", "type": "textarea", "label": "Something that already lets a little out:"}, {"id": "f3", "type": "textarea", "label": "One new way to pour off this week:"}, {"id": "f4", "type": "textarea", "label": "Who or what could help me carry some of it:"}]'::jsonb, array['stress', 'planning', 'self-monitoring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('doorway-threshold-reset-ritual-page', 'Doorway Threshold Reset Ritual Page', 'worksheet'::resource_kind, 'A planner for a short ritual that marks the move from work or school to home.', 'Use it to help a client build a brief ritual that separates one part of the day from the next.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to pick a doorway in their day, such as the front door, and design a short sequence to cross it. Small and repeatable works better than ambitious. Check in on whether it stays realistic after a week.', '[{"id": "f0", "type": "textarea", "label": "The doorway I cross each day:"}, {"id": "f1", "type": "textarea", "label": "What I usually carry through it:"}, {"id": "f2", "type": "textarea", "label": "Three small steps for my ritual:"}, {"id": "f3", "type": "textarea", "label": "What I want to leave behind at the door:"}, {"id": "f4", "type": "textarea", "label": "What I want to step into:"}]'::jsonb, array['routines', 'stress', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('unfinished-tasks-sorting-page', 'Unfinished Tasks Sorting Page', 'worksheet'::resource_kind, 'A page for sorting open tasks into do, delegate, schedule and let go.', 'Use it to help a client turn a crowded mind into a short list they can act on.', array['Adults']::text[], '25 minutes', 'Ask the client to list everything on their mind, then sort it into four groups. Notice where they get stuck, often on the let go group, and talk through it. End by choosing just one task for the next twenty-four hours.', '[{"id": "f0", "type": "textarea", "label": "Everything on my mind right now:"}, {"id": "f1", "type": "textarea", "label": "What I can do in under five minutes:"}, {"id": "f2", "type": "textarea", "label": "What I can hand to someone else:"}, {"id": "f3", "type": "textarea", "label": "What I will put on the calendar:"}, {"id": "f4", "type": "textarea", "label": "What I am choosing to let go of:"}]'::jsonb, array['planning', 'organization', 'routines']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('evening-wind-down-runway-sheet', 'Evening Wind-Down Runway Sheet', 'worksheet'::resource_kind, 'A sheet for planning the last hour before bed as a gentle runway.', 'Use it to help a client design a calming path from the end of the day toward sleep.', array['Adults', 'Teens']::text[], 'One week', 'Walk through the evening with the client and mark where screens, tasks and worries tend to creep in. Let them pick two or three wind-down steps, then track which ones felt doable. Adjust the runway at the next visit.', '[{"id": "f0", "type": "textarea", "label": "When my wind-down starts:"}, {"id": "f1", "type": "textarea", "label": "What usually pulls me off track:"}, {"id": "f2", "type": "textarea", "label": "Three things I will do on my runway:"}, {"id": "f3", "type": "textarea", "label": "What I will do if a worry shows up:"}, {"id": "f4", "type": "textarea", "label": "How the runway felt this week:"}]'::jsonb, array['sleep', 'routines', 'self-monitoring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('who-helps-with-what-concentric-rings-page', 'Who Helps With What Concentric Rings Page', 'worksheet'::resource_kind, 'A set of rings for placing the people who support a client and the kind of help each gives.', 'Use it to help a client see who they can turn to and for what.', array['Adults', 'Teens']::text[], '30 minutes', 'The client places names in rings by closeness and notes the kind of support each person offers, such as listening or practical help. Gaps are information, not failure. Explore one person they might reach out to this week.', '[{"id": "f0", "type": "textarea", "label": "People in my closest ring:"}, {"id": "f1", "type": "textarea", "label": "People in my middle ring:"}, {"id": "f2", "type": "textarea", "label": "What kind of help each person gives:"}, {"id": "f3", "type": "textarea", "label": "A kind of help I wish I had more of:"}, {"id": "f4", "type": "textarea", "label": "Someone I will reach out to this week:"}]'::jsonb, array['support', 'connection', 'relationships']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('who-else-shares-the-blame-pie-page', 'Who Else Shares the Blame Pie Page', 'cbt'::resource_kind, 'A pie chart exercise for sharing out the causes of an event rather than taking all of it.', 'Use it to help a client see the many factors behind an event they blame themselves for.', array['Adults', 'Teens']::text[], '30 minutes', 'The client names an event and lists every factor that played a part, then divides a pie among them, saving their own share for last. Expect their slice to shrink and notice how that feels. Ask what a fair share means to them.', '[{"id": "f0", "type": "textarea", "label": "The event I blame myself for:"}, {"id": "f1", "type": "textarea", "label": "Everyone and everything that played a part:"}, {"id": "f2", "type": "textarea", "label": "How I would slice the pie, leaving my part for last:"}, {"id": "f3", "type": "textarea", "label": "My slice at the end:"}, {"id": "f4", "type": "textarea", "label": "What I notice now:"}]'::jsonb, array['core CBT', 'guilt', 'cognitive restructuring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('what-would-that-say-about-me-ladder', 'What Would That Say About Me Ladder', 'cbt'::resource_kind, 'A ladder of follow-up questions that moves from a first thought to the belief under it.', 'Use it to help a client follow a thought down to the belief that gives it weight.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with an automatic thought and keep asking what it would mean if it were true, writing each answer on a lower rung. Go slowly and stop when the client reaches a belief that feels familiar. Pair it with a later look at the evidence.', '[{"id": "f0", "type": "textarea", "label": "The first thought:"}, {"id": "f1", "type": "textarea", "label": "If that were true, it would mean:"}, {"id": "f2", "type": "textarea", "label": "And if that were true, it would mean:"}, {"id": "f3", "type": "textarea", "label": "The belief at the bottom of the ladder:"}, {"id": "f4", "type": "textarea", "label": "How strongly I believe it right now, 0 to 10:"}, {"id": "f5", "type": "textarea", "label": "One small piece of evidence that does not fit:"}]'::jsonb, array['core beliefs', 'automatic thoughts', 'core CBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('shades-between-extremes-slider-page', 'Shades Between Extremes Slider Page', 'cbt'::resource_kind, 'A line from zero to one hundred for placing an all-or-nothing judgment among shades in between.', 'Use it to help a client move from all-or-nothing labels to a range.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names the extreme label they use on themselves or a situation, draws the line with both ends defined, then places people and events along it. Notice where they place themselves and invite a second look.', '[{"id": "f0", "type": "textarea", "label": "The all-or-nothing label I use:"}, {"id": "f1", "type": "textarea", "label": "What the very bottom of the line looks like:"}, {"id": "f2", "type": "textarea", "label": "What the very top looks like:"}, {"id": "f3", "type": "textarea", "label": "People or events I would place along the line:"}, {"id": "f4", "type": "textarea", "label": "Where I put myself, and why:"}, {"id": "f5", "type": "textarea", "label": "Where I might place myself on a kinder day:"}]'::jsonb, array['thinking traps', 'cognitive restructuring', 'self-criticism']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('three-column-future-outcomes-page', 'Three Column Future Outcomes Page', 'cbt'::resource_kind, 'A three-column page that sets a feared outcome beside the best and most likely ones.', 'Use it to help a client look past the worst case to the full set of possibilities.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes the worst outcome first, then the best, then the most likely, and rates how sure they are of each. Spend time on the likely column and on how they would cope. Follow up on what actually happened.', '[{"id": "f0", "type": "textarea", "label": "The situation I am dreading:"}, {"id": "f1", "type": "textarea", "label": "The worst outcome:"}, {"id": "f2", "type": "textarea", "label": "The best outcome:"}, {"id": "f3", "type": "textarea", "label": "The most likely outcome:"}, {"id": "f4", "type": "textarea", "label": "How I would cope if the worst happened:"}, {"id": "f5", "type": "textarea", "label": "How sure I am of each, 0 to 100:"}]'::jsonb, array['worry', 'predictions', 'decatastrophizing']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('hidden-crutch-habits-spotting-log', 'Hidden Crutch Habits Spotting Log', 'cbt'::resource_kind, 'A log for noticing small habits a client uses to feel safe and what they cost.', 'Use it to help a client spot the habits that keep a fear going and test dropping one.', array['Adults']::text[], 'One week', 'Invite the client to catch the little things they do to get through feared moments, such as checking or staying near an exit. List each one with what it protects and what it takes. Choose one to drop in a planned experiment.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "What I did to feel safe:"}, {"id": "f2", "type": "textarea", "label": "What I believe it prevented:"}, {"id": "f3", "type": "textarea", "label": "What it cost me:"}, {"id": "f4", "type": "textarea", "label": "A safety habit I could try dropping:"}, {"id": "f5", "type": "textarea", "label": "What I predict will happen if I do:"}]'::jsonb, array['safety behaviors', 'behavioral experiment', 'avoidance']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('shouting-riders-steering-wheel-role-play', 'Shouting Riders Steering Wheel Role Play', 'act'::resource_kind, 'A role play page that casts difficult thoughts as passengers while the client keeps driving.', 'Use it to help a client keep moving toward a value while unwelcome thoughts ride along.', array['Adults', 'Teens']::text[], '30 minutes', 'Name the bus, the direction the client chooses and the passengers who shout. Act it out, with you as a loud passenger if the client agrees. The point is not to silence them but to keep driving. Ask what the client would do next.', '[{"id": "f0", "type": "textarea", "label": "Where my bus is headed:"}, {"id": "f1", "type": "textarea", "label": "The loud passengers on my bus:"}, {"id": "f2", "type": "textarea", "label": "What they tell me to do:"}, {"id": "f3", "type": "textarea", "label": "What I do when I keep driving anyway:"}, {"id": "f4", "type": "textarea", "label": "What I need to bring on the trip:"}]'::jsonb, array['values', 'defusion', 'core ACT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('finger-trap-workability-page', 'Finger Trap Workability Page', 'act'::resource_kind, 'A page built around the finger trap image for testing whether struggling is getting the client anywhere.', 'Use it to help a client test whether fighting a feeling is working.', array['Adults', 'Teens']::text[], '25 minutes', 'Try a finger trap, if you have one, then ask what the client has been pulling against. List what they have tried and what each cost them. Workability is the question, not right or wrong. Close with one thing they might loosen.', '[{"id": "f0", "type": "textarea", "label": "What I have been pulling against:"}, {"id": "f1", "type": "textarea", "label": "Everything I have tried to get rid of it:"}, {"id": "f2", "type": "textarea", "label": "What those efforts cost me:"}, {"id": "f3", "type": "textarea", "label": "What worked, and for how long:"}, {"id": "f4", "type": "textarea", "label": "One thing I could loosen my grip on:"}]'::jsonb, array['workability', 'willingness', 'core ACT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('drifting-leaves-daily-watching-log', 'Drifting Leaves Daily Watching Log', 'act'::resource_kind, 'A log for practicing thoughts as leaves drifting by and noting what happened.', 'Use it to help a client practice watching thoughts float by without following them.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Walk through the leaves exercise once in session, then give the log for brief daily practice. Some days thoughts will not leave and that is fine to write down. Review what the client noticed rather than whether they did it right.', '[{"id": "f0", "type": "textarea", "label": "Where I practiced:"}, {"id": "f1", "type": "textarea", "label": "Thoughts that came up:"}, {"id": "f2", "type": "textarea", "label": "Which ones floated by and which ones stuck:"}, {"id": "f3", "type": "textarea", "label": "How my body felt:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about watching:"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('sunday-direction-reading-compass-sheet', 'Sunday Direction Reading Compass Sheet', 'act'::resource_kind, 'A compass sheet for taking a weekly reading on how closely actions followed chosen directions.', 'Use it to help a client check each week whether their actions point toward their values.', array['Adults']::text[], '20 minutes weekly', 'The client names three directions that matter and notes one action in each that week. Gaps are information to be curious about, not grounds for judgment. End by setting a small bearing for the coming week.', '[{"id": "f0", "type": "textarea", "label": "Three directions that matter to me:"}, {"id": "f1", "type": "textarea", "label": "One thing I did that moved me that way:"}, {"id": "f2", "type": "textarea", "label": "Where I drifted off course:"}, {"id": "f3", "type": "textarea", "label": "What got in the way:"}, {"id": "f4", "type": "textarea", "label": "My bearing for next week:"}]'::jsonb, array['values', 'committed action', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('effort-versus-feeling-struggle-dial', 'Effort Versus Feeling Struggle Dial', 'act'::resource_kind, 'A dial that tracks how hard a client is struggling with a feeling and what turning it down looks like.', 'Use it to help a client notice the struggle layered on top of a hard feeling.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw the switch and ask the client to rate the feeling and then the struggle against it. Explore what turning the struggle down would look like in practice, while leaving the feeling in place. Try it once in session.', '[{"id": "f0", "type": "textarea", "label": "The feeling I am having:"}, {"id": "f1", "type": "textarea", "label": "How hard I am struggling against it, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What the struggle looks like in my body:"}, {"id": "f3", "type": "textarea", "label": "What turning it down would look like:"}, {"id": "f4", "type": "textarea", "label": "What I could do with my time and energy if I did:"}]'::jsonb, array['acceptance', 'willingness', 'core ACT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('peak-distress-distraction-menu-builder', 'Peak Distress Distraction Menu Builder', 'dbt'::resource_kind, 'A menu of distraction skills a client builds from the ACCEPTS letters.', 'Use it to help a client choose distractions they will actually use when distress is high.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through each ACCEPTS letter and have the client write one specific idea that fits their life. Make it a menu they can photograph. Practice one item in session and remind them this is for riding out a peak, not for solving the problem.', '[{"id": "f0", "type": "textarea", "label": "Activities I could do:"}, {"id": "f1", "type": "textarea", "label": "Contributing to someone else:"}, {"id": "f2", "type": "textarea", "label": "Comparisons that help me:"}, {"id": "f3", "type": "textarea", "label": "Emotions I could invite instead:"}, {"id": "f4", "type": "textarea", "label": "Pushing away for a little while:"}, {"id": "f5", "type": "textarea", "label": "Thoughts to fill my mind:"}, {"id": "f6", "type": "textarea", "label": "Sensations I could use:"}]'::jsonb, array['distress tolerance', 'ACCEPTS', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('check-the-facts-fit-table', 'Check the Facts Fit Table', 'dbt'::resource_kind, 'A table for sorting what happened from what the client thinks it means and how well the emotion fits.', 'Use it to help a client test whether an emotion fits the facts of a situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk the client through naming the emotion, the event, their interpretations and the threat they see, then asking whether the intensity fits. Leave room for it to fit; the aim is accuracy, not talking them out of the feeling.', '[{"id": "f0", "type": "textarea", "label": "The emotion I am feeling:"}, {"id": "f1", "type": "textarea", "label": "What happened, only the facts:"}, {"id": "f2", "type": "textarea", "label": "What I am assuming about it:"}, {"id": "f3", "type": "textarea", "label": "The worst I am picturing:"}, {"id": "f4", "type": "textarea", "label": "Does my emotion and its strength fit the facts:"}, {"id": "f5", "type": "textarea", "label": "What I could do next:"}]'::jsonb, array['emotion regulation', 'check the facts', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('just-hard-enough-daily-challenge-log', 'Just Hard Enough Daily Challenge Log', 'dbt'::resource_kind, 'A log for choosing one doable challenge a day and noting how competence felt.', 'Use it to help a client build a sense of mastery through one small challenge a day.', array['Adults', 'Teens']::text[], 'One week', 'Have the client choose challenges that are slightly hard but possible, then log what they did and how it felt. Celebrate any attempt. Pair it with the pleasant-events log if the client has one.', '[{"id": "f0", "type": "textarea", "label": "Today''s challenge:"}, {"id": "f1", "type": "textarea", "label": "Why I picked it:"}, {"id": "f2", "type": "textarea", "label": "What I did:"}, {"id": "f3", "type": "textarea", "label": "How I felt afterward:"}, {"id": "f4", "type": "textarea", "label": "What I will try tomorrow:"}]'::jsonb, array['emotion regulation', 'mastery', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('keep-the-relationship-in-mind-conversation-planner', 'Keep the Relationship in Mind Conversation Planner', 'dbt'::resource_kind, 'A planner for rehearsing the GIVE skills before a conversation that matters.', 'Use it to help a client plan how to keep a relationship in mind during a hard conversation.', array['Adults', 'Teens']::text[], '25 minutes', 'Before a conversation, the client writes how they will be Gentle, Interested, Validate and keep an Easy manner. Rehearse a short exchange in session and revisit afterward. Name which letter was hardest.', '[{"id": "f0", "type": "textarea", "label": "The conversation I have coming up:"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle:"}, {"id": "f2", "type": "textarea", "label": "How I will show interest:"}, {"id": "f3", "type": "textarea", "label": "What I can validate about the other person:"}, {"id": "f4", "type": "textarea", "label": "How I will keep an easy manner:"}, {"id": "f5", "type": "textarea", "label": "What I want from this conversation:"}]'::jsonb, array['interpersonal effectiveness', 'GIVE', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('soft-face-open-palms-body-stance-card', 'Soft Face Open Palms Body Stance Card', 'dbt'::resource_kind, 'A card for pairing a half smile with willing hands to soften body stance during distress.', 'Use it to help a client use the body to practice acceptance when emotions run high.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice both postures in session, relaxing the face and turning palms up. Explore where the client notices resistance. It is a body-based way to practice willingness, one small part of the skill set the client can choose to use.', '[{"id": "f0", "type": "textarea", "label": "When I could use this:"}, {"id": "f1", "type": "textarea", "label": "What my face does when I am upset:"}, {"id": "f2", "type": "textarea", "label": "How the half smile felt:"}, {"id": "f3", "type": "textarea", "label": "How willing hands felt:"}, {"id": "f4", "type": "textarea", "label": "What I noticed after:"}]'::jsonb, array['acceptance', 'distress tolerance', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('hopes-under-the-argument-interview-sheet', 'Hopes Under the Argument Interview Sheet', 'couples'::resource_kind, 'A sheet for finding the dream or value underneath a recurring disagreement.', 'Use it to help partners hear what matters beneath a gridlocked argument.', array['Couples']::text[], '45 minutes', 'Each partner takes a turn speaking about what the issue means to them while the other only listens and asks curious questions. Look for the story, history or hope under the position. The goal is understanding, not agreement.', '[{"id": "f0", "type": "textarea", "label": "Partner A: The issue we keep returning to:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What it means to me:"}, {"id": "f2", "type": "textarea", "label": "Partner A: A hope underneath it:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What I heard my partner say:"}, {"id": "f4", "type": "textarea", "label": "Partner B: What it means to me:"}, {"id": "f5", "type": "textarea", "label": "Partner B: A hope underneath it:"}]'::jsonb, array['Gottman', 'conflict', 'communication']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('small-reaches-noticed-weekly-tally', 'Small Reaches Noticed Weekly Tally', 'couples'::resource_kind, 'A weekly page for noticing small bids for attention and how each partner responded.', 'Use it to help partners notice small bids for connection and turn toward them.', array['Couples']::text[], 'One week', 'Introduce bids as small reaches, like a comment or a touch. Each partner tallies bids they made and ones they noticed. Review without scoring; look for patterns of missed bids and what makes turning toward easier.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Bids I made this week:"}, {"id": "f1", "type": "textarea", "label": "Partner A: Bids I noticed from my partner:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Bids I made this week:"}, {"id": "f3", "type": "textarea", "label": "Partner B: Bids I noticed from my partner:"}, {"id": "f4", "type": "textarea", "label": "Together: A bid that went well, and why:"}, {"id": "f5", "type": "textarea", "label": "Together: One bid we could make more of:"}]'::jsonb, array['Gottman', 'connection', 'check-in']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('harsh-opener-to-soft-opener-rewrite-sheet', 'Harsh Opener to Soft Opener Rewrite Sheet', 'couples'::resource_kind, 'A page for rewriting a harsh opening complaint into a gentle startup.', 'Use it to help partners open a hard topic with a feeling and a request instead of blame.', array['Couples']::text[], '30 minutes', 'Each partner writes a typical harsh opener, then rewrites it using I feel, about what, and I need. Read both aloud and practice in session. Notice how it lands for the listener, and revisit the rewrite if it still stings.', '[{"id": "f0", "type": "textarea", "label": "Partner A: How I usually begin:"}, {"id": "f1", "type": "textarea", "label": "Partner A: My gentle rewrite, with a feeling and a request:"}, {"id": "f2", "type": "textarea", "label": "Partner B: How I usually begin:"}, {"id": "f3", "type": "textarea", "label": "Partner B: My gentle rewrite, with a feeling and a request:"}, {"id": "f4", "type": "textarea", "label": "Together: What we noticed when we heard each version:"}]'::jsonb, array['communication', 'Gottman', 'conflict']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('what-money-means-to-each-of-us-guide', 'What Money Means to Each of Us Guide', 'couples'::resource_kind, 'A guide for talking through what money means to each partner and what they want it to do.', 'Use it to help partners talk about money through shared values rather than blame.', array['Couples']::text[], '45 minutes', 'Each partner explores what money meant growing up and what they want it to make possible, before any numbers are discussed. Name differences with curiosity. Finish with one small joint agreement to try for a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What money meant in my family:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What I want money to do for us:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What money meant in my family:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What I want money to do for us:"}, {"id": "f4", "type": "textarea", "label": "Where our values overlap:"}, {"id": "f5", "type": "textarea", "label": "One small agreement we will try:"}]'::jsonb, array['values', 'negotiation', 'relationship issues']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('specific-thank-you-trade-letters', 'Specific Thank-You Trade Letters', 'couples'::resource_kind, 'A page where partners write specific appreciations and trade them aloud.', 'Use it to help partners say specific thank-yous that they rarely get to hear.', array['Couples']::text[], '30 minutes', 'Each partner writes three specific things they appreciated lately, with what it meant to them. They read them aloud in turns while the other receives without deflecting. Notice what is hard about taking appreciation in.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Three things I appreciate, with details:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What it meant to me:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Three things I appreciate, with details:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What it meant to me:"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear it:"}]'::jsonb, array['appreciation', 'connection', 'communication']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('rainy-sunny-window-feelings-frame', 'Rainy Sunny Window Feelings Frame', 'kids'::resource_kind, 'A craft where a child draws weather in a window frame to show how they feel today.', 'Use it to help a child name feelings through weather pictures.', array['Children']::text[], '25 minutes', 'The child draws a window and fills it with sun, rain, storm or fog for how they feel. The parent draws their own window and tells about it too. Parents can use the window as a daily check-in, and nothing a child draws needs fixing.', '[{"id": "f0", "type": "textarea", "label": "My weather today:"}, {"id": "f1", "type": "textarea", "label": "What makes my weather change:"}, {"id": "f2", "type": "textarea", "label": "What I do when a storm comes:"}, {"id": "f3", "type": "textarea", "label": "Who I want near me in a storm:"}]'::jsonb, array['children', 'emotion identification', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('glitter-settling-jar-build-along', 'Glitter Settling Jar Build-Along', 'kids'::resource_kind, 'A build-it page for making a glitter jar and a plan for when to use it.', 'Use it to help a child watch feelings settle like glitter and use the jar when upset.', array['Children']::text[], '30 minutes', 'The child and parent fill a jar with water, glue and glitter, shake it and watch. The parent sits beside the child while it settles and breathes with them. Choose a spot at home where it lives and let the child decide when to use it.', '[{"id": "f0", "type": "textarea", "label": "Colors I picked for my jar:"}, {"id": "f1", "type": "textarea", "label": "How my body feels when I shake it up:"}, {"id": "f2", "type": "textarea", "label": "What I see while it settles:"}, {"id": "f3", "type": "textarea", "label": "When I could use my jar:"}, {"id": "f4", "type": "textarea", "label": "Where our jar will live:"}]'::jsonb, array['children', 'self-soothing', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('cape-of-strengths-hero-drawing', 'Cape of Strengths Hero Drawing', 'kids'::resource_kind, 'A drawing activity where a child designs a cape showing their strengths.', 'Use it to help a child name and draw the strengths they bring to hard moments.', array['Children']::text[], '30 minutes', 'The child draws a cape and decorates it with symbols of what they are good at or kind about. The parent adds one strength they have noticed. Display the cape somewhere the child sees it, and avoid ranking strengths against other children.', '[{"id": "f0", "type": "textarea", "label": "My superhero name:"}, {"id": "f1", "type": "textarea", "label": "What is on my cape:"}, {"id": "f2", "type": "textarea", "label": "A strength I used this week:"}, {"id": "f3", "type": "textarea", "label": "A strength my parent sees in me:"}]'::jsonb, array['children', 'strengths', 'art']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('climb-up-courage-steps-picture', 'Climb Up Courage Steps Picture', 'kids'::resource_kind, 'A drawing of a staircase where each step is a slightly braver thing to try.', 'Use it to help a child break a scary task into small brave steps.', array['Children']::text[], '30 minutes', 'The child draws a staircase and the parent helps them write or draw each step from easiest to hardest. They choose one step to try this week with the parent beside them. Praise trying, not just finishing, and let them pick the pace.', '[{"id": "f0", "type": "textarea", "label": "The big thing I want to do:"}, {"id": "f1", "type": "textarea", "label": "Step one, the easiest:"}, {"id": "f2", "type": "textarea", "label": "Step two:"}, {"id": "f3", "type": "textarea", "label": "Step three:"}, {"id": "f4", "type": "textarea", "label": "The step I will try this week:"}]'::jsonb, array['children', 'exposure', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('mixed-up-feelings-sorting-bottles-craft', 'Mixed-Up Feelings Sorting Bottles Craft', 'kids'::resource_kind, 'A craft with labeled bottles for sorting feelings that come in mixed colors.', 'Use it to help a child see that more than one feeling can be present at once.', array['Children']::text[], '30 minutes', 'Set out bottles or cups with colors for feelings and let the child fill them to show a mix of feelings about an event. The parent shows a mix of their own. Ask what each color wants, and keep it playful.', '[{"id": "f0", "type": "textarea", "label": "The event I picked:"}, {"id": "f1", "type": "textarea", "label": "The feelings I poured in:"}, {"id": "f2", "type": "textarea", "label": "Which one is biggest:"}, {"id": "f3", "type": "textarea", "label": "Which one surprised me:"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('act-it-out-emotion-guessing-game', 'Act It Out Emotion Guessing Game', 'game'::resource_kind, 'A charades game where players act out feelings and guess them.', 'Use it to help clients read and show feelings through body language.', array['Groups', 'Children', 'Teens']::text[], '30 minutes', 'Players draw a card with a feeling and act it out without words while others guess. After each round, ask what clue gave it away and when they have felt it. Let anyone pass, and keep the debrief on how feelings show up in the body.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out:"}, {"id": "f1", "type": "textarea", "label": "What gave it away:"}, {"id": "f2", "type": "textarea", "label": "A time I felt it:"}, {"id": "f3", "type": "textarea", "label": "What I learned about reading others:"}]'::jsonb, array['group', 'emotion identification', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('coping-skills-bingo-group-card', 'Coping Skills Bingo Group Card', 'game'::resource_kind, 'A bingo card of coping skills players check off as the group names and shares them.', 'Use it to help a group share coping ideas and add to each other''s toolboxes.', array['Groups', 'Teens']::text[], '30 minutes', 'Fill each square with a coping skill, then call or share them in turns. A player marks a square when they have used that skill and tells the group how it went. In the debrief, each person picks one new idea to try.', '[{"id": "f0", "type": "textarea", "label": "Skills I already use:"}, {"id": "f1", "type": "textarea", "label": "A square I had not tried:"}, {"id": "f2", "type": "textarea", "label": "What someone shared that I liked:"}, {"id": "f3", "type": "textarea", "label": "One skill I will try this week:"}]'::jsonb, array['group', 'coping skills', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('kinder-angle-hot-potato-circle-game', 'Kinder Angle Hot Potato Circle Game', 'game'::resource_kind, 'A circle game where a thought is passed around and each person offers one kinder angle.', 'Use it to help a group practice flexible thinking out loud.', array['Groups', 'Teens']::text[], '30 minutes', 'One player offers a harsh thought about a made-up situation and passes it. Each person adds one alternate view that feels honest. After a round, debrief which reframes felt believable and which felt forced.', '[{"id": "f0", "type": "textarea", "label": "The thought we passed:"}, {"id": "f1", "type": "textarea", "label": "The reframe I offered:"}, {"id": "f2", "type": "textarea", "label": "The reframe that felt most believable:"}, {"id": "f3", "type": "textarea", "label": "What I will remember:"}]'::jsonb, array['group', 'cognitive restructuring', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('spend-your-pretend-money-on-values-auction', 'Spend Your Pretend Money on Values Auction', 'game'::resource_kind, 'An auction where players use pretend money to bid on the values they care about most.', 'Use it to help clients notice which values they will spend their limited resources on.', array['Groups', 'Teens', 'Adults']::text[], '45 minutes', 'Give each player the same amount of pretend money and a list of values to bid on. Not everyone gets everything, which is the point. Debrief on what they chose, what they let go of and how it matches their real lives.', '[{"id": "f0", "type": "textarea", "label": "The values I wanted most:"}, {"id": "f1", "type": "textarea", "label": "What I spent on them:"}, {"id": "f2", "type": "textarea", "label": "What I let go of:"}, {"id": "f3", "type": "textarea", "label": "What surprised me:"}, {"id": "f4", "type": "textarea", "label": "How my real week matches my bids:"}]'::jsonb, array['values', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('soft-ball-toss-stressors-and-skills-round', 'Soft Ball Toss Stressors and Skills Round', 'game'::resource_kind, 'A toss game where catching the ball means naming a coping skill or a stress.', 'Use it to help a group name stressors and skills in a quick, light format.', array['Groups', 'Teens']::text[], '25 minutes', 'Standing in a circle, players toss a soft ball and the catcher names a stressor or a skill, alternating by round. Slow it down as people warm up. Debrief on which skills came up often and which were new.', '[{"id": "f0", "type": "textarea", "label": "A stressor I named:"}, {"id": "f1", "type": "textarea", "label": "A skill I named:"}, {"id": "f2", "type": "textarea", "label": "A skill someone else named that I want:"}, {"id": "f3", "type": "textarea", "label": "What I will use this week:"}]'::jsonb, array['group', 'coping skills', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('too-hot-too-cold-just-right-zones-page', 'Too Hot Too Cold Just Right Zones Page', 'worksheet'::resource_kind, 'A page for marking when a client feels too revved up, too shut down or settled.', 'Use it to help a client notice where they are and pick a way back toward steady.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw three zones with the client and have them mark how each feels in the body. Keep it in the present and on pacing; no one needs to describe what happened. Choose one steadying move for each zone they can reach on their own.', '[{"id": "f0", "type": "textarea", "label": "How I feel when I am revved up:"}, {"id": "f1", "type": "textarea", "label": "How I feel when I am shut down:"}, {"id": "f2", "type": "textarea", "label": "How I feel when I am settled:"}, {"id": "f3", "type": "textarea", "label": "Where I am right now:"}, {"id": "f4", "type": "textarea", "label": "One steadying move I can try:"}]'::jsonb, array['PTSD and trauma', 'pacing', 'grounding']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('today-s-date-and-place-reminder-page', 'Today''s Date and Place Reminder Page', 'cbt'::resource_kind, 'A page that helps a client place a startling reminder in the past and check what is true now.', 'Use it to help a client tell the difference between a reminder and present danger.', array['Adults']::text[], '20 minutes', 'The client names a reminder that jolted them and writes what is different today, such as the date, place and who is around. Stay with the present details and do not ask for the story of the past event. Offer to practice it as a grounding tool.', '[{"id": "f0", "type": "textarea", "label": "The reminder I noticed:"}, {"id": "f1", "type": "textarea", "label": "What my body did:"}, {"id": "f2", "type": "textarea", "label": "Today''s date and where I am:"}, {"id": "f3", "type": "textarea", "label": "What is different now:"}, {"id": "f4", "type": "textarea", "label": "What I can do to help my body settle:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('carrying-hard-memories-with-values-page', 'Carrying Hard Memories With Values Page', 'act'::resource_kind, 'A page about carrying painful memories while still moving toward what matters.', 'Use it to help a client make room for hard memories while taking steps that matter to them.', array['Adults']::text[], '30 minutes', 'Keep the focus on what the client wants more of in life, not on the content of any memory. Ask what they have avoided because of reminders and what a small step toward a value could be. Let them set the pace and stop at any time.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me:"}, {"id": "f1", "type": "textarea", "label": "What has felt out of reach:"}, {"id": "f2", "type": "textarea", "label": "What I would need to carry with me:"}, {"id": "f3", "type": "textarea", "label": "One small step I would choose:"}, {"id": "f4", "type": "textarea", "label": "Who could be beside me:"}]'::jsonb, array['PTSD and trauma', 'values', 'committed action']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('crisis-survival-kit-for-overwhelm-page', 'Crisis Survival Kit for Overwhelm Page', 'dbt'::resource_kind, 'A page for building a box of skills to use when memories or reminders feel too big.', 'Use it to help a client gather distress tolerance skills for overwhelming moments.', array['Adults', 'Teens']::text[], '30 minutes', 'Build the kit with the client around the five senses and a few reminders about where they are. If thoughts of suicide or self-harm come up, name 988 (call or text) and complete the safety plan in session. Practice a skill together before sending it home.', '[{"id": "f0", "type": "textarea", "label": "Things I can see that calm me:"}, {"id": "f1", "type": "textarea", "label": "Things I can hear:"}, {"id": "f2", "type": "textarea", "label": "Things I can touch or hold:"}, {"id": "f3", "type": "textarea", "label": "A reminder of where and when I am:"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I will call or text 988 or:"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'safety']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('my-safe-spot-and-safe-grown-ups-picture', 'My Safe Spot and Safe Grown-Ups Picture', 'kids'::resource_kind, 'A drawing of a place that feels safe and the people who help a child feel protected.', 'Use it to help a child picture safety and name trusted adults.', array['Children']::text[], '30 minutes', 'The child draws a safe place and the people they would go to. The parent says what they will do to help. Do not ask for details of any frightening event. If a child discloses harm, remember your reporting duties and follow them.', '[{"id": "f0", "type": "textarea", "label": "My safe place looks like:"}, {"id": "f1", "type": "textarea", "label": "What I can see there:"}, {"id": "f2", "type": "textarea", "label": "The people who help me feel safe:"}, {"id": "f3", "type": "textarea", "label": "What I do when I feel scared:"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('early-flutter-body-outline-page', 'Early Flutter Body Outline Page', 'worksheet'::resource_kind, 'A body outline where a client marks where anxiety shows up and what each signal tells them.', 'Use it to help a client spot early body signals of anxiety and choose a response.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client color the places they notice tightness, heat or flutter, and name what usually comes before each. Early signals give them a chance to act. Choose one signal to practice noticing this week.', '[{"id": "f0", "type": "textarea", "label": "Where I feel anxiety first:"}, {"id": "f1", "type": "textarea", "label": "What it feels like there:"}, {"id": "f2", "type": "textarea", "label": "What usually happens just before:"}, {"id": "f3", "type": "textarea", "label": "What I tend to do next:"}, {"id": "f4", "type": "textarea", "label": "What I could try instead:"}]'::jsonb, array['anxiety', 'self-monitoring', 'body']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('what-if-questions-answer-ladder', 'What If Questions Answer Ladder', 'cbt'::resource_kind, 'A ladder that moves from a what if worry to what I would do and what is likely.', 'Use it to help a client answer their what ifs with plans and likelihoods.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes a what if worry and then answers it three ways: how likely, what I would do and what I would tell a friend. Notice if the worry is a problem to solve or one to let sit. Work on one at a time.', '[{"id": "f0", "type": "textarea", "label": "My what if worry:"}, {"id": "f1", "type": "textarea", "label": "How likely I think it is, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "If it happened, what I would do:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend:"}, {"id": "f4", "type": "textarea", "label": "Is this a problem I can solve today:"}]'::jsonb, array['anxiety', 'worry', 'core CBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('anxiety-weather-station-daily-page', 'Anxiety Weather Station Daily Page', 'act'::resource_kind, 'A page for describing anxiety as weather passing through while the client does something that matters.', 'Use it to help a client carry anxiety along while acting on what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'The client describes the forecast inside them and what they want to do anyway. Practice naming it, such as there is a storm of worry, and choosing an action. Check in on what they did and how the weather moved.', '[{"id": "f0", "type": "textarea", "label": "Today''s forecast inside me:"}, {"id": "f1", "type": "textarea", "label": "What I want to do anyway:"}, {"id": "f2", "type": "textarea", "label": "What the storm tells me to do:"}, {"id": "f3", "type": "textarea", "label": "What I did while it was there:"}, {"id": "f4", "type": "textarea", "label": "How the weather changed:"}]'::jsonb, array['anxiety', 'defusion', 'willingness']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-exhale-longer-card', 'Paced Breathing and Exhale Longer Card', 'dbt'::resource_kind, 'A card for practicing paced breathing with a longer exhale and noting how it feels.', 'Use it to help a client practice a quick body skill for anxious moments.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice breathing with the client, in for four and out for six, and watch for light-headedness. Encourage them to stop if it feels bad. Track the practice over a week and discuss when it helped.', '[{"id": "f0", "type": "textarea", "label": "When I will practice:"}, {"id": "f1", "type": "textarea", "label": "How my body felt before:"}, {"id": "f2", "type": "textarea", "label": "How my body felt after:"}, {"id": "f3", "type": "textarea", "label": "When I will use it this week:"}, {"id": "f4", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['anxiety', 'distress tolerance', 'breathing']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('worries-in-a-hat-shared-draw-game', 'Worries in a Hat Shared Draw Game', 'game'::resource_kind, 'A game where worries go in a hat and the group draws one to suggest a next step.', 'Use it to help a group share worries and trade practical ideas.', array['Groups', 'Teens']::text[], '40 minutes', 'Players write a worry anonymously and drop it in a hat. Each draws one and reads it aloud, and the group offers one idea or a kind word. Debrief on what it was like to hear that others worry too. Let anyone pass.', '[{"id": "f0", "type": "textarea", "label": "The worry I put in:"}, {"id": "f1", "type": "textarea", "label": "An idea I offered:"}, {"id": "f2", "type": "textarea", "label": "An idea I might try:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hear others'' worries:"}]'::jsonb, array['anxiety', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('heavy-day-energy-coins-page', 'Heavy Day Energy Coins Page', 'worksheet'::resource_kind, 'A page for spending a small daily energy budget on what matters most.', 'Use it to help a client choose where limited energy goes on low days.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client rate their energy on a low day and list tasks with their cost. Pick one thing for the body, one for others and one for meaning. Review what felt possible and avoid turning it into a standard to meet.', '[{"id": "f0", "type": "textarea", "label": "My energy today, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "Tasks I feel I must do and what each costs:"}, {"id": "f2", "type": "textarea", "label": "One thing for my body:"}, {"id": "f3", "type": "textarea", "label": "One thing for someone else:"}, {"id": "f4", "type": "textarea", "label": "One thing that matters to me:"}]'::jsonb, array['depression', 'pacing', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('mood-lift-activity-experiment-page', 'Mood Lift Activity Experiment Page', 'cbt'::resource_kind, 'A page that predicts how a small activity will change mood, then compares it to what happened.', 'Use it to help a client test what a small activity actually does to their mood.', array['Adults', 'Teens']::text[], 'One week', 'Choose a small activity together and have the client rate their mood before, predict, and rate again after. Review the gap between prediction and result. Low mood often forecasts that nothing will help, so go gently.', '[{"id": "f0", "type": "textarea", "label": "The activity I chose:"}, {"id": "f1", "type": "textarea", "label": "My mood before, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I predict it will do:"}, {"id": "f3", "type": "textarea", "label": "My mood after:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the difference:"}]'::jsonb, array['depression', 'behavioral activation', 'behavioral experiment']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('values-seeds-in-low-mood-planting-page', 'Values Seeds in Low Mood Planting Page', 'act'::resource_kind, 'A page for planting small value-based actions even when motivation is missing.', 'Use it to help a client take one small step toward a value without waiting for motivation.', array['Adults']::text[], '25 minutes', 'The client names a value and chooses a seed-sized action for it, such as a text or a walk to the mailbox. Reflect on what grew. Treat missed days as information and plant again.', '[{"id": "f0", "type": "textarea", "label": "A value I still care about:"}, {"id": "f1", "type": "textarea", "label": "A seed-sized action for it:"}, {"id": "f2", "type": "textarea", "label": "What my mood says about doing it:"}, {"id": "f3", "type": "textarea", "label": "What I did anyway:"}, {"id": "f4", "type": "textarea", "label": "What happened:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('do-the-opposite-of-withdrawing-plan', 'Do the Opposite of Withdrawing Plan', 'dbt'::resource_kind, 'A planner that pairs the urge to withdraw with an opposite action.', 'Use it to help a client choose an opposite action when low mood pulls them to withdraw.', array['Adults', 'Teens']::text[], '25 minutes', 'The client names the urge, such as staying in bed, and what the feeling says. Choose a small opposite action and check that it fits the facts. If thoughts of suicide arise, name 988 (call or text) and handle it in session.', '[{"id": "f0", "type": "textarea", "label": "What my mood is telling me to do:"}, {"id": "f1", "type": "textarea", "label": "What I usually do:"}, {"id": "f2", "type": "textarea", "label": "A small opposite action:"}, {"id": "f3", "type": "textarea", "label": "When I will do it:"}, {"id": "f4", "type": "textarea", "label": "If my thoughts get dark, I will call or text 988 or:"}]'::jsonb, array['depression', 'opposite action', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('feelings-flower-bed-drawing', 'Feelings Flower Bed Drawing', 'kids'::resource_kind, 'A drawing of a garden where each plant shows a feeling and what helps it grow.', 'Use it to help a child name low or heavy feelings and what helps them feel lighter.', array['Children']::text[], '30 minutes', 'The child draws a garden with plants for feelings, including sad ones. The parent adds what the child likes doing that is like sunshine or water. Keep the tone gentle and do not push for cheerfulness. Tell the clinician if sadness lingers.', '[{"id": "f0", "type": "textarea", "label": "The feelings in my garden:"}, {"id": "f1", "type": "textarea", "label": "Which plant is biggest today:"}, {"id": "f2", "type": "textarea", "label": "What is like sunshine for me:"}, {"id": "f3", "type": "textarea", "label": "Who waters my garden with me:"}]'::jsonb, array['depression', 'children', 'art']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('time-blindness-visual-timer-plan-page', 'Time Blindness Visual Timer Plan Page', 'worksheet'::resource_kind, 'A page for making time visible with timers, blocks and checkpoints.', 'Use it to help a client make time visible for tasks they lose track of.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one task the client often loses time on, estimate how long it takes, then compare with a trial. Plan visible timers and a checkpoint. Compare estimates over a week and be matter-of-fact about gaps.', '[{"id": "f0", "type": "textarea", "label": "A task I lose track of:"}, {"id": "f1", "type": "textarea", "label": "How long I think it takes:"}, {"id": "f2", "type": "textarea", "label": "How long it took:"}, {"id": "f3", "type": "textarea", "label": "Where I will place a visible timer:"}, {"id": "f4", "type": "textarea", "label": "A checkpoint I will use:"}]'::jsonb, array['ADHD', 'organization', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('task-start-barrier-breakdown-page', 'Task Start Barrier Breakdown Page', 'cbt'::resource_kind, 'A page for naming what blocks starting a task and shrinking the first step.', 'Use it to help a client find what blocks starting and make the first step tiny.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names a task they put off, the thought that shows up and the smallest first move. Shrink it until it takes two minutes. Check in on what the thought was and whether the step happened.', '[{"id": "f0", "type": "textarea", "label": "The task I keep delaying:"}, {"id": "f1", "type": "textarea", "label": "The thought that shows up:"}, {"id": "f2", "type": "textarea", "label": "What makes starting hard:"}, {"id": "f3", "type": "textarea", "label": "A two-minute first step:"}, {"id": "f4", "type": "textarea", "label": "When I will do it:"}]'::jsonb, array['ADHD', 'procrastination', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('dull-task-to-meaningful-reason-bridge', 'Dull Task to Meaningful Reason Bridge', 'act'::resource_kind, 'A page for linking tasks that feel dull to something the client values.', 'Use it to help a client connect an uninteresting task to a reason that matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a task that lacks interest and ask what it makes possible. Write the bridge in the client''s words. Pair with a small reward or body double and review what helped.', '[{"id": "f0", "type": "textarea", "label": "The task I find dull:"}, {"id": "f1", "type": "textarea", "label": "What it makes possible:"}, {"id": "f2", "type": "textarea", "label": "Why that matters to me:"}, {"id": "f3", "type": "textarea", "label": "What would help me start:"}, {"id": "f4", "type": "textarea", "label": "What I will do after:"}]'::jsonb, array['ADHD', 'values', 'motivation']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('household-reminder-agreement-sheet', 'Household Reminder Agreement Sheet', 'couples'::resource_kind, 'A sheet for partners to agree on how reminders are given without nagging.', 'Use it to help partners agree on reminders that help without feeling like criticism.', array['Couples']::text[], '40 minutes', 'The partner with attention difficulties says what kinds of reminders help, and the other partner says what they would like to hand off. Choose a system together, such as a shared list, and a tone for requests. Review it in a week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What reminders help me:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What feels like nagging:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I would like to stop carrying:"}, {"id": "f3", "type": "textarea", "label": "Our agreed system:"}, {"id": "f4", "type": "textarea", "label": "How we will check in on it:"}]'::jsonb, array['ADHD', 'couples', 'negotiation']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('side-by-side-ten-minute-sprint-game', 'Side by Side Ten Minute Sprint Game', 'game'::resource_kind, 'A game where partners work side by side in short timed sprints and cheer completions.', 'Use it to help clients try short focus sprints with a partner for company.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Pairs set a ten-minute timer, each working on their own task. After each sprint, they share what they finished and give a cheer. Debrief on what kept attention and what pulled it away. Adjust sprint length to the client.', '[{"id": "f0", "type": "textarea", "label": "My task for the sprint:"}, {"id": "f1", "type": "textarea", "label": "How long I stayed with it:"}, {"id": "f2", "type": "textarea", "label": "What pulled my attention:"}, {"id": "f3", "type": "textarea", "label": "What helped:"}]'::jsonb, array['ADHD', 'focus', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('rise-peak-fall-urge-timeline-page', 'Rise Peak Fall Urge Timeline Page', 'worksheet'::resource_kind, 'A page for tracking when substance use urges rise, peak and pass.', 'Use it to help a client notice that urges rise and fall and plan for the peak.', array['Adults']::text[], 'One week', 'The client logs when an urge appears, what came before, how strong it got and how long it lasted. Look for patterns in time and place. Note what helped it pass without judging urges that were acted on.', '[{"id": "f0", "type": "textarea", "label": "When the urge started:"}, {"id": "f1", "type": "textarea", "label": "What was happening before:"}, {"id": "f2", "type": "textarea", "label": "How strong it got, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I did:"}, {"id": "f4", "type": "textarea", "label": "How long it lasted:"}]'::jsonb, array['addiction', 'urges', 'substance use']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('if-this-urge-then-that-plan-table', 'If This Urge Then That Plan Table', 'cbt'::resource_kind, 'A table pairing triggers for substance use with a plan for each.', 'Use it to help a client name triggers and decide ahead what they will do.', array['Adults']::text[], '30 minutes', 'List people, places, feelings and times that raise urges, then write an if-then plan for each. Role-play one. Revise the plan after a real situation and keep the tone curious.', '[{"id": "f0", "type": "textarea", "label": "A trigger:"}, {"id": "f1", "type": "textarea", "label": "What I feel and think when it shows up:"}, {"id": "f2", "type": "textarea", "label": "What I used to do:"}, {"id": "f3", "type": "textarea", "label": "My if-then plan:"}, {"id": "f4", "type": "textarea", "label": "Who I can reach out to:"}]'::jsonb, array['addiction', 'triggers', 'substance use']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('days-worth-living-values-page', 'Days Worth Living Values Page', 'act'::resource_kind, 'A page for exploring what a client wants their days to be about beyond substance use.', 'Use it to help a client connect choices about substance use to what they value.', array['Adults']::text[], '30 minutes', 'Ask what the client wants in relationships, work and health and what substance use costs or gives them in each. Avoid labeling; keep to the client''s words. Pick one small step toward a value this week.', '[{"id": "f0", "type": "textarea", "label": "What I want my days to be about:"}, {"id": "f1", "type": "textarea", "label": "What substance use has given me:"}, {"id": "f2", "type": "textarea", "label": "What it has cost me:"}, {"id": "f3", "type": "textarea", "label": "A value I want to move toward:"}, {"id": "f4", "type": "textarea", "label": "A step I will take this week:"}]'::jsonb, array['addiction', 'values', 'substance use']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('ride-the-urge-wave-card', 'Ride the Urge Wave Card', 'dbt'::resource_kind, 'A card for riding out an urge by noticing it rise, crest and fall.', 'Use it to help a client practice riding out an urge without acting on it.', array['Adults']::text[], '20 minutes', 'Practice in session with a mild urge, such as wanting to check a phone. Have the client describe where it sits and how it changes. Then plan how to use it for substance use urges, with support from their care team.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge:"}, {"id": "f1", "type": "textarea", "label": "What it feels like:"}, {"id": "f2", "type": "textarea", "label": "How it changed over a few minutes:"}, {"id": "f3", "type": "textarea", "label": "What I told myself:"}, {"id": "f4", "type": "textarea", "label": "When I will use this:"}]'::jsonb, array['addiction', 'urges', 'distress tolerance']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-card-sort-game', 'Pros and Cons Card Sort Game', 'game'::resource_kind, 'A card sort game where players sort reasons for and against change.', 'Use it to help clients sort the reasons that pull them in both directions about substance use.', array['Groups', 'Adults']::text[], '40 minutes', 'Players write reasons on cards and sort them into for and against, then rate how much each matters. Debrief on what surprised them. Keep it nonjudgmental and note that ambivalence is common.', '[{"id": "f0", "type": "textarea", "label": "A reason I wrote down:"}, {"id": "f1", "type": "textarea", "label": "Which pile it went in:"}, {"id": "f2", "type": "textarea", "label": "What matters most to me:"}, {"id": "f3", "type": "textarea", "label": "What surprised me:"}]'::jsonb, array['addiction', 'ambivalence', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('anger-temperature-rise-log', 'Anger Temperature Rise Log', 'worksheet'::resource_kind, 'A log for noting what raises anger, how hot it gets and what cools it.', 'Use it to help a client notice their anger rising earlier and cool it sooner.', array['Adults', 'Teens']::text[], 'One week', 'The client logs what happened, where they felt it, how hot it got and what they did. Look for the early signals and a moment when a pause is possible. Do not shame the high points.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body:"}, {"id": "f2", "type": "textarea", "label": "How hot it got, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I did:"}, {"id": "f4", "type": "textarea", "label": "What cooled it:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('anger-thought-and-alternative-page', 'Anger Thought and Alternative Page', 'cbt'::resource_kind, 'A page for catching the hot thought under anger and writing a cooler one.', 'Use it to help a client slow the thoughts that fuel anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Help the client find the should or blame thought in a recent flare and write a cooler thought that is still honest. Invite them to rate anger before and after. It is not about dropping the feeling but having choices.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "The hot thought:"}, {"id": "f2", "type": "textarea", "label": "How angry I was, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "A cooler thought:"}, {"id": "f4", "type": "textarea", "label": "How angry I am now:"}]'::jsonb, array['anger management', 'cognitive restructuring', 'thinking traps']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('time-out-plan-for-anger-card', 'Time-Out Plan for Anger Card', 'dbt'::resource_kind, 'A card for leaving a heated moment, calming down and coming back.', 'Use it to help a client take a planned break and return to the conversation.', array['Adults', 'Teens']::text[], '20 minutes', 'Agree on how the client will say they need a break, where they will go and what they will do to cool down. Plan a time to return. Practice the sentence aloud, and review how it went.', '[{"id": "f0", "type": "textarea", "label": "The sentence I will say:"}, {"id": "f1", "type": "textarea", "label": "Where I will go:"}, {"id": "f2", "type": "textarea", "label": "What I will do to cool down:"}, {"id": "f3", "type": "textarea", "label": "When I will come back:"}, {"id": "f4", "type": "textarea", "label": "What I will say when I return:"}]'::jsonb, array['anger management', 'distress tolerance', 'STOP']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('cooling-off-and-return-agreement-sheet', 'Cooling Off and Return Agreement Sheet', 'couples'::resource_kind, 'A sheet for partners to agree on how to pause a heated argument and return to it.', 'Use it to help partners pause a heated argument without leaving the other behind.', array['Couples']::text[], '35 minutes', 'Each partner writes the sign that they are getting heated and the break they need. Together, they agree on a signal and a return time. Role-play the signal. Check in later on what made returning easier.', '[{"id": "f0", "type": "textarea", "label": "Partner A: My early sign:"}, {"id": "f1", "type": "textarea", "label": "Partner B: My early sign:"}, {"id": "f2", "type": "textarea", "label": "Our signal for a break:"}, {"id": "f3", "type": "textarea", "label": "What each of us does while apart:"}, {"id": "f4", "type": "textarea", "label": "When we come back:"}]'::jsonb, array['anger management', 'couples', 'conflict']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('paper-volcano-build-and-cool-steps', 'Paper Volcano Build and Cool Steps', 'kids'::resource_kind, 'A craft where a child builds a paper volcano and picks cool-down steps.', 'Use it to help a child spot anger building and choose a cool-down.', array['Children']::text[], '30 minutes', 'The child builds a volcano from paper and writes what makes it heat up and what cools it. The parent practices a cool-down with the child. Praise the cool-down, not the absence of anger. Let the parent offer a cool-down hint.', '[{"id": "f0", "type": "textarea", "label": "What makes my volcano heat up:"}, {"id": "f1", "type": "textarea", "label": "How my body feels as it heats:"}, {"id": "f2", "type": "textarea", "label": "What helps it cool:"}, {"id": "f3", "type": "textarea", "label": "What my parent can do to help:"}]'::jsonb, array['anger management', 'children', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-sticky-note-page', 'Intrusive Thought Sticky Note Page', 'worksheet'::resource_kind, 'A page for labeling an intrusive thought as just a thought and recording what the client did next.', 'Use it to help a client watch intrusive thoughts without getting pulled into rituals.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes the thought, labels it as an intrusive thought, and records what they did next. Notice the urge to act and what it promised. Do not invite reassurance; talk about what could be tried instead.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought:"}, {"id": "f1", "type": "textarea", "label": "How much it bothered me, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I felt like doing:"}, {"id": "f3", "type": "textarea", "label": "What I did:"}, {"id": "f4", "type": "textarea", "label": "What I could try next time:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'self-monitoring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('ritual-delay-timer-ladder-steps', 'Ritual Delay Timer Ladder Steps', 'cbt'::resource_kind, 'A ladder of feared situations ranked by difficulty with notes on holding off a ritual.', 'Use it to help a client plan graded steps and hold off a ritual at each one.', array['Adults']::text[], '40 minutes', 'Build the ladder with the client from easiest to hardest and set the first step. At each step, agree on how long they will wait before any ritual. Rate distress before and after, and review in session rather than alone at first.', '[{"id": "f0", "type": "textarea", "label": "The first step I will try:"}, {"id": "f1", "type": "textarea", "label": "The ritual I will hold off on:"}, {"id": "f2", "type": "textarea", "label": "How long I will wait:"}, {"id": "f3", "type": "textarea", "label": "My distress before, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "My distress after:"}]'::jsonb, array['OCD', 'exposure', 'response prevention']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('thanks-mind-doubt-labeling-page', 'Thanks Mind Doubt Labeling Page', 'act'::resource_kind, 'A page for labeling doubts as thoughts and choosing actions by values instead.', 'Use it to help a client label doubt as a thought and choose actions by what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes the doubt in a phrase such as I am having the thought that, and then notes what they want to do. Ask what they value and what a values-based action could be. Review which doubts return most.', '[{"id": "f0", "type": "textarea", "label": "The doubt that showed up:"}, {"id": "f1", "type": "textarea", "label": "I am having the thought that:"}, {"id": "f2", "type": "textarea", "label": "What it asked me to do:"}, {"id": "f3", "type": "textarea", "label": "What matters to me here:"}, {"id": "f4", "type": "textarea", "label": "The action I chose:"}]'::jsonb, array['OCD', 'defusion', 'values']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('bossy-worry-comic-strip-craft', 'Bossy Worry Comic Strip Craft', 'kids'::resource_kind, 'A craft where a child draws their worry bully and writes talk-back lines.', 'Use it to help a child talk back to a bossy worry instead of obeying it.', array['Children']::text[], '30 minutes', 'The child draws the bully, names it and writes what it bosses them to do. The parent learns not to give extra reassurance and instead cheers a brave try. Plan one small thing the child will try with the bully nearby.', '[{"id": "f0", "type": "textarea", "label": "What my worry bully looks like:"}, {"id": "f1", "type": "textarea", "label": "What it bosses me to do:"}, {"id": "f2", "type": "textarea", "label": "What I want to say back:"}, {"id": "f3", "type": "textarea", "label": "One small thing I will try:"}]'::jsonb, array['OCD', 'children', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('roll-a-maybe-uncertainty-practice-game', 'Roll a Maybe Uncertainty Practice Game', 'game'::resource_kind, 'A dice game where rolls decide short practice tasks in not knowing for sure.', 'Use it to help clients practice tolerating not knowing for sure in small ways.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Players roll a die that assigns a small uncertainty task, such as leaving an item unchecked, and share how it felt. Keep tasks mild and agreed ahead. Debrief on what they noticed and what they will try in daily life.', '[{"id": "f0", "type": "textarea", "label": "The task I rolled:"}, {"id": "f1", "type": "textarea", "label": "What I felt:"}, {"id": "f2", "type": "textarea", "label": "What I did instead of a ritual:"}, {"id": "f3", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['OCD', 'uncertainty', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('panic-wave-notes-and-aftermath-page', 'Panic Wave Notes and Aftermath Page', 'worksheet'::resource_kind, 'A page for recording a panic wave, what the body did and how it passed.', 'Use it to help a client see how a panic wave rose and passed.', array['Adults', 'Teens']::text[], 'One week', 'The client logs what was happening, the body sensations, the thoughts and when it eased. Look for the pattern of rise and fall. Talk about what the client did to ride it out and what they might try next.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what was happening:"}, {"id": "f1", "type": "textarea", "label": "What my body did:"}, {"id": "f2", "type": "textarea", "label": "What I thought:"}, {"id": "f3", "type": "textarea", "label": "When it began to pass:"}, {"id": "f4", "type": "textarea", "label": "What I did that helped:"}]'::jsonb, array['panic attacks', 'self-monitoring', 'body']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('racing-heart-other-explanations-page', 'Racing Heart Other Explanations Page', 'cbt'::resource_kind, 'A page for testing what a body sensation might mean beyond danger.', 'Use it to help a client try other explanations for sensations that feel alarming.', array['Adults']::text[], '25 minutes', 'The client lists a sensation and what they fear it means, then others ways to explain it. Rate belief in each. Agree on how to follow up on any physical concern with their doctor, since you are not reading the body.', '[{"id": "f0", "type": "textarea", "label": "The sensation:"}, {"id": "f1", "type": "textarea", "label": "What I fear it means:"}, {"id": "f2", "type": "textarea", "label": "Other things it could be:"}, {"id": "f3", "type": "textarea", "label": "How much I believe each, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "What I will check with my doctor, if anything:"}]'::jsonb, array['panic attacks', 'thinking traps', 'body']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('panic-passenger-willingness-page', 'Panic Passenger Willingness Page', 'act'::resource_kind, 'A page for making room for panic sensations while staying on the path.', 'Use it to help a client allow panic sensations and keep going toward what matters.', array['Adults']::text[], '25 minutes', 'The client names what they avoid because of panic and what matters about it. Practice noticing and allowing a sensation for a minute in session. Then choose a small step with the sensation along for the ride.', '[{"id": "f0", "type": "textarea", "label": "What I avoid because of panic:"}, {"id": "f1", "type": "textarea", "label": "What matters to me about it:"}, {"id": "f2", "type": "textarea", "label": "What I notice when I allow the feeling:"}, {"id": "f3", "type": "textarea", "label": "The step I will take:"}, {"id": "f4", "type": "textarea", "label": "What I will say to the feeling:"}]'::jsonb, array['panic attacks', 'willingness', 'acceptance']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('cold-water-face-and-paced-breath-plan', 'Cold Water Face and Paced Breath Plan', 'dbt'::resource_kind, 'A plan for using cool water on the face and slow breath during a panic wave.', 'Use it to help a client prepare a quick body plan for a panic wave.', array['Adults', 'Teens']::text[], '20 minutes', 'Check with the client about health concerns before using cool water. Practice cool water on the face and a slow exhale in session. Write the plan on a card they can keep with them and revisit after real use.', '[{"id": "f0", "type": "textarea", "label": "When I will use this plan:"}, {"id": "f1", "type": "textarea", "label": "What I will do first:"}, {"id": "f2", "type": "textarea", "label": "What I will do next:"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself:"}, {"id": "f4", "type": "textarea", "label": "Who I can tell:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'TIPP']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('rocket-breathing-and-calm-launch-page', 'Rocket Breathing and Calm Launch Page', 'kids'::resource_kind, 'A page where a child colors a rocket and practices breathing as the countdown.', 'Use it to help a child try slow breathing through a playful rocket countdown.', array['Children']::text[], '20 minutes', 'The child colors a rocket and the parent counts a slow breath out for the launch. Practice together when calm so it is ready for a hard moment. Let the child set the countdown number and do it with the parent.', '[{"id": "f0", "type": "textarea", "label": "My rocket looks like:"}, {"id": "f1", "type": "textarea", "label": "How my body feels at the start:"}, {"id": "f2", "type": "textarea", "label": "How my body feels after the launch:"}, {"id": "f3", "type": "textarea", "label": "When we will use it:"}]'::jsonb, array['panic attacks', 'children', 'breathing']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('two-or-three-daily-anchors-for-families-page', 'Two or Three Daily Anchors for Families Page', 'worksheet'::resource_kind, 'A page for choosing two or three daily anchors that give a child predictability.', 'Use it to help a parent set a few steady routines a child can count on.', array['Adults']::text[], '25 minutes', 'Parents pick two or three anchor moments, such as mornings and bedtime, and write what will happen in each. Keep them small. Review how the child responded and adjust to what the family can hold.', '[{"id": "f0", "type": "textarea", "label": "The anchor moments in our day:"}, {"id": "f1", "type": "textarea", "label": "What happens in each:"}, {"id": "f2", "type": "textarea", "label": "What gets in the way:"}, {"id": "f3", "type": "textarea", "label": "What I will try first:"}, {"id": "f4", "type": "textarea", "label": "How I will know it helped:"}]'::jsonb, array['parenting', 'routines', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('harsh-thought-catch-for-tired-parents-page', 'Harsh Thought Catch for Tired Parents Page', 'cbt'::resource_kind, 'A page for catching harsh thoughts about a child or oneself in tough moments.', 'Use it to help a parent catch a stressed thought and find one that helps.', array['Adults']::text[], '25 minutes', 'The parent writes a hard moment, the thought about the child or about themselves, and a more balanced thought. Ask what they would want to do with the balanced thought. Be kind about how hard the day was.', '[{"id": "f0", "type": "textarea", "label": "The hard moment:"}, {"id": "f1", "type": "textarea", "label": "The thought I had about my child or myself:"}, {"id": "f2", "type": "textarea", "label": "How I felt and what I did:"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought:"}, {"id": "f4", "type": "textarea", "label": "What I would do next time:"}]'::jsonb, array['parenting', 'cognitive restructuring', 'stress']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('parent-i-hope-to-be-letter-page', 'Parent I Hope to Be Letter Page', 'act'::resource_kind, 'A page for naming the parent a person wants to be and a small action for it.', 'Use it to help a parent connect daily choices to the kind of parent they want to be.', array['Adults']::text[], '30 minutes', 'Ask what the parent wants their child to remember about them and what they value, then choose one small action this week. Treat slips with compassion; the question is what they want to do next.', '[{"id": "f0", "type": "textarea", "label": "The parent I want to be:"}, {"id": "f1", "type": "textarea", "label": "What I want my child to remember:"}, {"id": "f2", "type": "textarea", "label": "A hard moment that tests this:"}, {"id": "f3", "type": "textarea", "label": "One action I will take this week:"}, {"id": "f4", "type": "textarea", "label": "What could get in my way:"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('same-page-three-rules-caregiver-sheet', 'Same Page Three Rules Caregiver Sheet', 'couples'::resource_kind, 'A sheet for two caregivers to agree on a few shared household rules.', 'Use it to help caregivers agree on a short list of rules and how they will back each other.', array['Couples']::text[], '45 minutes', 'Each caregiver lists the rules that matter most. Together they choose three to hold the same way and decide how to back each other. Plan how to handle a disagreement in the moment, privately and later.', '[{"id": "f0", "type": "textarea", "label": "Caregiver A: The rules that matter most to me:"}, {"id": "f1", "type": "textarea", "label": "Caregiver B: The rules that matter most to me:"}, {"id": "f2", "type": "textarea", "label": "Three rules we will hold together:"}, {"id": "f3", "type": "textarea", "label": "How we back each other:"}, {"id": "f4", "type": "textarea", "label": "How we will handle disagreement in front of our child:"}]'::jsonb, array['parenting', 'couples', 'negotiation']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('spin-and-share-family-feelings-spinner', 'Spin and Share Family Feelings Spinner', 'kids'::resource_kind, 'A craft wheel a family spins to check in on feelings at dinner or bedtime.', 'Use it to help a family build a routine of naming feelings together.', array['Children', 'Adults']::text[], '30 minutes', 'The child and parent make a wheel with feelings, spin it and each shares a time they felt it that day. The parent goes first and accepts all feelings without fixing. Use it a few nights a week and see what the child adds.', '[{"id": "f0", "type": "textarea", "label": "Feelings on our wheel:"}, {"id": "f1", "type": "textarea", "label": "The one I landed on today:"}, {"id": "f2", "type": "textarea", "label": "A time I felt it:"}, {"id": "f3", "type": "textarea", "label": "What helps me when I feel it:"}]'::jsonb, array['parenting', 'children', 'emotion identification']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('postpartum-support-plan-week-page', 'Postpartum Support Plan Week Page', 'worksheet'::resource_kind, 'A page for mapping helpers, tasks and rest across a week with a new baby.', 'Use it to help a new parent line up help and protect rest.', array['Adults']::text[], '30 minutes', 'The parent lists tasks and people who could take them and marks times for rest. Aim for a realistic plan and name one ask they will make. Include a plan for who to call and contact numbers if they feel unsafe, and 988 (call or text) for crisis.', '[{"id": "f0", "type": "textarea", "label": "Tasks that feel heavy:"}, {"id": "f1", "type": "textarea", "label": "People who could help:"}, {"id": "f2", "type": "textarea", "label": "When I will rest:"}, {"id": "f3", "type": "textarea", "label": "One ask I will make this week:"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I will call or text 988 or:"}]'::jsonb, array['perinatal and postpartum', 'support', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('perfect-parent-pressure-thought-record', 'Perfect Parent Pressure Thought Record', 'cbt'::resource_kind, 'A thought record about the pressure to do everything perfectly with a new baby.', 'Use it to help a parent test thoughts that they are failing their baby.', array['Adults']::text[], '25 minutes', 'The parent writes a harsh thought from a hard moment and the evidence for and against. Draft a good enough thought. Be warm, and encourage mentioning ongoing low mood or worry to their care team.', '[{"id": "f0", "type": "textarea", "label": "The harsh thought:"}, {"id": "f1", "type": "textarea", "label": "What happened:"}, {"id": "f2", "type": "textarea", "label": "Evidence that supports it:"}, {"id": "f3", "type": "textarea", "label": "Evidence that does not:"}, {"id": "f4", "type": "textarea", "label": "A good enough thought:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'self-criticism']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('sleepless-season-small-meaning-page', 'Sleepless Season Small Meaning Page', 'act'::resource_kind, 'A page for finding small values-based moments in a tiring, changing time.', 'Use it to help a new parent find small moments that matter amid exhaustion.', array['Adults']::text[], '25 minutes', 'Ask what the parent wants from this season and which two-minute moments could reflect it. Honor how tiring it is and avoid more to-dos. Notice what felt good this week.', '[{"id": "f0", "type": "textarea", "label": "What this season is asking of me:"}, {"id": "f1", "type": "textarea", "label": "What I value most right now:"}, {"id": "f2", "type": "textarea", "label": "A two-minute moment that reflects it:"}, {"id": "f3", "type": "textarea", "label": "What feels heavy:"}, {"id": "f4", "type": "textarea", "label": "What I will let go of:"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('night-block-split-sheet-for-new-parents', 'Night Block Split Sheet for New Parents', 'couples'::resource_kind, 'A sheet for partners to share nights, feeds and rest fairly.', 'Use it to help partners plan nights and rest so both get some sleep.', array['Couples']::text[], '40 minutes', 'Partners map who does what by block of time and mark protected rest. Check how each feels about it. Revisit weekly since a baby''s patterns change. Include one appreciation each.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What I can take on:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I can take on:"}, {"id": "f2", "type": "textarea", "label": "Our plan for nights:"}, {"id": "f3", "type": "textarea", "label": "When each of us rests:"}, {"id": "f4", "type": "textarea", "label": "An appreciation for my partner:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('five-minute-senses-breaks-between-feeds', 'Five Minute Senses Breaks Between Feeds', 'dbt'::resource_kind, 'A card of five-senses soothing ideas that fit into a baby''s schedule.', 'Use it to help a parent find brief soothing moments that fit around a baby.', array['Adults']::text[], '20 minutes', 'Have the parent write one idea per sense that takes under five minutes. Check which ones fit nap times. Encourage them to try one a day and share what helped.', '[{"id": "f0", "type": "textarea", "label": "Something to see:"}, {"id": "f1", "type": "textarea", "label": "Something to hear:"}, {"id": "f2", "type": "textarea", "label": "Something to smell:"}, {"id": "f3", "type": "textarea", "label": "Something to taste:"}, {"id": "f4", "type": "textarea", "label": "Something to touch:"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'core DBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('critic-lines-coach-replies-two-column-page', 'Critic Lines Coach Replies Two Column Page', 'worksheet'::resource_kind, 'A two-column page that rewrites critic lines in a coach''s voice.', 'Use it to help a client hear their critic and answer in a steadier voice.', array['Adults', 'Teens']::text[], '25 minutes', 'The client lists critic lines on the left and writes a coach''s reply on the right, in the tone they would use with someone they care about. Read both aloud. Notice which replies feel false and revise them.', '[{"id": "f0", "type": "textarea", "label": "A line my inner critic says:"}, {"id": "f1", "type": "textarea", "label": "How it makes me feel:"}, {"id": "f2", "type": "textarea", "label": "What a coach would say instead:"}, {"id": "f3", "type": "textarea", "label": "How that lands:"}, {"id": "f4", "type": "textarea", "label": "A line I will keep:"}]'::jsonb, array['self-esteem', 'self-criticism', 'self-compassion']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('new-belief-daily-proof-collection-log', 'New Belief Daily Proof Collection Log', 'cbt'::resource_kind, 'A log for collecting daily evidence for a more balanced belief about oneself.', 'Use it to help a client gather evidence for a new belief rather than only the old one.', array['Adults', 'Teens']::text[], 'One week', 'Choose an old belief and a more balanced one together. The client logs one daily event that fits the new belief, even if small. Review the log and look for evidence they discounted.', '[{"id": "f0", "type": "textarea", "label": "The old belief:"}, {"id": "f1", "type": "textarea", "label": "The balanced belief I want to test:"}, {"id": "f2", "type": "textarea", "label": "Today''s evidence:"}, {"id": "f3", "type": "textarea", "label": "How much I believe it, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "Something I discounted:"}]'::jsonb, array['self-esteem', 'core beliefs', 'core CBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('self-as-story-versus-self-as-observer-page', 'Self as Story Versus Self as Observer Page', 'act'::resource_kind, 'A page for noticing the story about oneself and the observer who sees it.', 'Use it to help a client step back from a fixed story about themselves.', array['Adults']::text[], '25 minutes', 'The client writes the story they tell about themselves and then notices who is noticing it. Ask what they would do if the story were only a story. Pick one action for the week.', '[{"id": "f0", "type": "textarea", "label": "The story I tell about myself:"}, {"id": "f1", "type": "textarea", "label": "Who notices this story:"}, {"id": "f2", "type": "textarea", "label": "What the story tells me to avoid:"}, {"id": "f3", "type": "textarea", "label": "What I would do if it were just a story:"}, {"id": "f4", "type": "textarea", "label": "My action this week:"}]'::jsonb, array['self-esteem', 'self as context', 'defusion']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('me-poster-of-likes-skills-and-cares', 'Me Poster of Likes Skills and Cares', 'kids'::resource_kind, 'A poster where a child draws or writes what they like, are good at and care about.', 'Use it to help a child notice and show what is good about them.', array['Children']::text[], '30 minutes', 'The child makes a poster with sections for things they like, are good at and care about. The parent adds a note of appreciation. Hang it where the child sees it and avoid comparing to others.', '[{"id": "f0", "type": "textarea", "label": "Things I like:"}, {"id": "f1", "type": "textarea", "label": "Things I am good at:"}, {"id": "f2", "type": "textarea", "label": "Things I care about:"}, {"id": "f3", "type": "textarea", "label": "What my parent likes about me:"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('compliment-circle-with-receiving-practice', 'Compliment Circle With Receiving Practice', 'game'::resource_kind, 'A group game where players offer compliments and practice receiving them.', 'Use it to help a group practice giving and accepting kind words.', array['Groups', 'Teens']::text[], '30 minutes', 'In turns, one player is the receiver and others offer a specific, true compliment. The receiver says only thank you. Debrief on how hard it was to receive. Allow players to pass.', '[{"id": "f0", "type": "textarea", "label": "A compliment I gave:"}, {"id": "f1", "type": "textarea", "label": "A compliment I received:"}, {"id": "f2", "type": "textarea", "label": "What it was like to say thank you:"}, {"id": "f3", "type": "textarea", "label": "What I want to remember:"}]'::jsonb, array['self-esteem', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('social-situation-dread-and-reality-page', 'Social Situation Dread and Reality Page', 'worksheet'::resource_kind, 'A page comparing predicted social dread with what happened afterward.', 'Use it to help a client compare dread beforehand with what really happened.', array['Adults', 'Teens']::text[], 'One week', 'Before an event, the client writes their prediction and rating. Afterward, they write what happened. Look at the gap and what they would try next. Keep the events small to begin with.', '[{"id": "f0", "type": "textarea", "label": "The event:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f2", "type": "textarea", "label": "How anxious I expect to be, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "How anxious I really was:"}]'::jsonb, array['social anxiety', 'predictions', 'exposure']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('look-outward-conversation-trial-page', 'Look Outward Conversation Trial Page', 'cbt'::resource_kind, 'A page for shifting attention from self-monitoring to the other person and the room.', 'Use it to help a client test what happens when attention moves outward.', array['Adults', 'Teens']::text[], '25 minutes', 'The client tries a short conversation once focused on themselves and once on the other person, and compares. Notice how self-focus affects their view of how they came across. Plan another trial.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "How I felt when I watched myself:"}, {"id": "f2", "type": "textarea", "label": "How I felt when I watched the other person:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in the room:"}, {"id": "f4", "type": "textarea", "label": "What I will try next:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'attention']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('nervous-but-connected-step-page', 'Nervous but Connected Step Page', 'act'::resource_kind, 'A page connecting a social step to a value, with room for the anxious feelings.', 'Use it to help a client take a social step for a reason, with nerves along.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what a social connection would give the client and which step toward it feels doable. Name the feelings likely to come. Decide how they will carry them and check in afterward.', '[{"id": "f0", "type": "textarea", "label": "Why connection matters to me:"}, {"id": "f1", "type": "textarea", "label": "A social step I could take:"}, {"id": "f2", "type": "textarea", "label": "The nerves I expect:"}, {"id": "f3", "type": "textarea", "label": "How I will carry them:"}, {"id": "f4", "type": "textarea", "label": "What I did:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('dear-man-practice-for-social-situations', 'DEAR MAN Practice for Social Situations', 'dbt'::resource_kind, 'A page for drafting a DEAR MAN to ask or say no in a social situation.', 'Use it to help a client rehearse asking for what they want or saying no.', array['Adults', 'Teens']::text[], '30 minutes', 'The client picks a small request, writes each part, and rehearses aloud with you. Notice what they skip, often the Assert step. Try it in real life and report back.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "Describe and Express:"}, {"id": "f2", "type": "textarea", "label": "Assert:"}, {"id": "f3", "type": "textarea", "label": "Reinforce:"}, {"id": "f4", "type": "textarea", "label": "Mindful, Appear confident, Negotiate:"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('pick-a-card-easy-questions-game', 'Pick a Card Easy Questions Game', 'game'::resource_kind, 'A card game with low-stakes conversation starters for taking turns.', 'Use it to help clients practice low-stakes conversation in a supportive group.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Players draw a card with a simple question and answer, then ask a follow-up. Start with easy cards and let players pass. Debrief on what they noticed about their fears and what actually happened.', '[{"id": "f0", "type": "textarea", "label": "The card I drew:"}, {"id": "f1", "type": "textarea", "label": "How anxious I felt, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What happened when I answered:"}, {"id": "f3", "type": "textarea", "label": "What I will try with someone this week:"}]'::jsonb, array['social anxiety', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('aching-moments-and-what-soothes-them-log', 'Aching Moments and What Soothes Them Log', 'worksheet'::resource_kind, 'A page for noting when grief rises and what comforts at those times.', 'Use it to help a client notice grief waves and what comfort fits.', array['Adults', 'Teens']::text[], 'One week', 'The client logs when grief rises, what set it off and what brought comfort. There is no right way to grieve. Look for patterns and gentle supports they can plan for anniversaries and hard times.', '[{"id": "f0", "type": "textarea", "label": "When grief came up:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "How strong it felt, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What comforted me:"}, {"id": "f4", "type": "textarea", "label": "What I will plan for hard days:"}]'::jsonb, array['grief and loss', 'self-monitoring', 'self-compassion']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('grief-thoughts-and-balanced-thoughts-page', 'Grief Thoughts and Balanced Thoughts Page', 'cbt'::resource_kind, 'A page for looking at thoughts like I should have and finding gentler views.', 'Use it to help a client look at guilt and should thoughts after a loss.', array['Adults']::text[], '25 minutes', 'Invite the client to write I should have thoughts and look at what they knew at the time. Draft a thought that holds both love and limits. Go slowly and let sadness be present.', '[{"id": "f0", "type": "textarea", "label": "The thought I keep having:"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A balanced thought:"}, {"id": "f4", "type": "textarea", "label": "How I feel now:"}]'::jsonb, array['grief and loss', 'guilt', 'cognitive restructuring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('honoring-what-i-loved-action-page', 'Honoring What I Loved Action Page', 'act'::resource_kind, 'A page about what the loss shows the client cares about and how to honor it.', 'Use it to help a client honor what they loved while still living.', array['Adults']::text[], '30 minutes', 'Ask what the relationship meant and what values it points to. Choose a small way to honor it. Stay with feelings as they come; there is nothing to fix.', '[{"id": "f0", "type": "textarea", "label": "Who or what I lost:"}, {"id": "f1", "type": "textarea", "label": "What it meant to me:"}, {"id": "f2", "type": "textarea", "label": "What that shows I value:"}, {"id": "f3", "type": "textarea", "label": "A small way I could honor it:"}, {"id": "f4", "type": "textarea", "label": "What I need from others:"}]'::jsonb, array['grief and loss', 'values', 'committed action']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('remembrance-box-build-and-fill-craft', 'Remembrance Box Build and Fill Craft', 'kids'::resource_kind, 'A craft where a child decorates a box for keepsakes and memories of someone they lost.', 'Use it to help a child hold memories of someone who died or left.', array['Children']::text[], '40 minutes', 'The child decorates a box and picks items or drawings to put in. The parent shares a memory too. Let the child ask questions and use simple, honest words. Return to it on hard days.', '[{"id": "f0", "type": "textarea", "label": "Who my box is for:"}, {"id": "f1", "type": "textarea", "label": "What I put in it:"}, {"id": "f2", "type": "textarea", "label": "My favorite memory:"}, {"id": "f3", "type": "textarea", "label": "What I wish I could tell them:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('story-prompt-circle-for-missing-someone', 'Story Prompt Circle for Missing Someone', 'game'::resource_kind, 'A circle where players share a memory from prompts about someone they miss.', 'Use it to help a group share memories of someone they miss in a gentle way.', array['Groups', 'Adults', 'Teens']::text[], '40 minutes', 'Players draw a prompt, such as a favorite saying, and share if they like. Others listen without advice. Allow passes and pauses and have a calm-down option ready.', '[{"id": "f0", "type": "textarea", "label": "The prompt I drew:"}, {"id": "f1", "type": "textarea", "label": "The memory I shared:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear others:"}, {"id": "f3", "type": "textarea", "label": "What I will take with me:"}]'::jsonb, array['grief and loss', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('complaint-to-clear-ask-converter', 'Complaint to Clear Ask Converter', 'worksheet'::resource_kind, 'A page for turning a vague complaint into a need and a clear ask.', 'Use it to help a client turn frustration into a need and a clear request.', array['Adults']::text[], '25 minutes', 'The client writes a complaint and works toward the need beneath it and a specific, doable ask. Check that the ask is something the other person can say yes or no to. Role-play it before trying it.', '[{"id": "f0", "type": "textarea", "label": "The complaint:"}, {"id": "f1", "type": "textarea", "label": "What I need underneath:"}, {"id": "f2", "type": "textarea", "label": "A clear, doable ask:"}, {"id": "f3", "type": "textarea", "label": "How I will say it:"}, {"id": "f4", "type": "textarea", "label": "What I will do if the answer is no:"}]'::jsonb, array['relationship issues', 'boundaries', 'communication']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('ask-instead-of-guess-check-out-page', 'Ask Instead of Guess Check-Out Page', 'cbt'::resource_kind, 'A page for noting a guess about a partner''s thoughts and checking it out.', 'Use it to help a client check a guess about someone''s thoughts before acting on it.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes the guess, how sure they are, and a way to ask. Practice the wording. After the check, compare the guess with what was said and note what changed.', '[{"id": "f0", "type": "textarea", "label": "What I assumed they thought:"}, {"id": "f1", "type": "textarea", "label": "How sure I was, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "How I could ask:"}, {"id": "f3", "type": "textarea", "label": "What they said:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the gap:"}]'::jsonb, array['relationship issues', 'thinking traps', 'communication']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrase-menu-for-couples', 'Repair Attempt Phrase Menu for Couples', 'couples'::resource_kind, 'A menu of phrases each partner can use mid-argument to repair.', 'Use it to help partners pick repair phrases that fit them and use them early.', array['Couples']::text[], '30 minutes', 'Each partner picks phrases that would work on them, such as can we start over, and shares them with the other. Practice using one in a mild disagreement. Revisit which ones helped.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Phrases that would help me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Phrases that would help me:"}, {"id": "f2", "type": "textarea", "label": "Our shared repair words:"}, {"id": "f3", "type": "textarea", "label": "A time we could have used one:"}, {"id": "f4", "type": "textarea", "label": "How we will remind ourselves:"}]'::jsonb, array['relationship issues', 'repair', 'Gottman']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('fair-truthful-self-respect-script-card', 'Fair Truthful Self-Respect Script Card', 'dbt'::resource_kind, 'A card for keeping fair, apologizing less, sticking to values and staying truthful.', 'Use it to help a client keep self-respect while asking or saying no.', array['Adults', 'Teens']::text[], '25 minutes', 'Go through each letter with a real situation. The client decides where they tend to give in. Rehearse a short script that stays fair and true to their values. Debrief on how it felt.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "Being fair:"}, {"id": "f2", "type": "textarea", "label": "No over-apologizing:"}, {"id": "f3", "type": "textarea", "label": "Sticking to my values:"}, {"id": "f4", "type": "textarea", "label": "Being truthful:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'FAST']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('trade-chairs-conflict-role-swap-game', 'Trade Chairs Conflict Role Swap Game', 'game'::resource_kind, 'A role play game where players swap sides in a conflict and speak as the other person.', 'Use it to help clients step into another''s view during a conflict.', array['Groups', 'Adults', 'Teens']::text[], '40 minutes', 'Pairs play out a mild disagreement, then swap roles and replay it. Debrief on what each noticed when speaking as the other. Keep the topic low-stakes and allow stopping at any time.', '[{"id": "f0", "type": "textarea", "label": "The conflict we played:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in the other role:"}, {"id": "f2", "type": "textarea", "label": "What changed for me:"}, {"id": "f3", "type": "textarea", "label": "What I might say differently:"}]'::jsonb, array['relationship issues', 'empathy', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('steady-ground-people-and-places-page', 'Steady Ground People and Places Page', 'worksheet'::resource_kind, 'A page for naming safe people, places and steps without discussing what happened.', 'Use it to help a client map who and where feels safe right now.', array['Adults', 'Teens']::text[], '25 minutes', 'The client lists people they trust, places that feel safe and steps they can take if they feel unsafe. Do not ask for details of past events and let them pace themselves. Go over local support lines and 988 (call or text) if crisis arises.', '[{"id": "f0", "type": "textarea", "label": "People I trust:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f2", "type": "textarea", "label": "What I can do if I feel unsafe:"}, {"id": "f3", "type": "textarea", "label": "Who I can call or text, including 988:"}, {"id": "f4", "type": "textarea", "label": "One thing that helps me feel steady:"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('body-trust-rebuilding-small-steps-page', 'Body Trust Rebuilding Small Steps Page', 'cbt'::resource_kind, 'A page for small steps of rebuilding trust in one''s body at the client''s pace.', 'Use it to help a client choose small, safe steps at their own pace.', array['Adults']::text[], '25 minutes', 'Focus on what the client chooses and controls, such as a stretch they pick. Stop whenever they want. Never ask for details of what happened. Review which steps felt safe.', '[{"id": "f0", "type": "textarea", "label": "A small step I could choose:"}, {"id": "f1", "type": "textarea", "label": "What I want to be in charge of:"}, {"id": "f2", "type": "textarea", "label": "How my body feels as I choose:"}, {"id": "f3", "type": "textarea", "label": "What I do if I want to stop:"}, {"id": "f4", "type": "textarea", "label": "Who knows my plan:"}]'::jsonb, array['sexual abuse', 'pacing', 'grounding']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('compassion-anchor-values-page', 'Compassion Anchor Values Page', 'act'::resource_kind, 'A page for naming what the client wants for themselves and one self-kind action.', 'Use it to help a client move toward what they value with self-kindness.', array['Adults']::text[], '30 minutes', 'Ask what the client wants for their life and what a kind step might be, with no need to speak of the past. Let the client define the pace. Check in on what felt safe.', '[{"id": "f0", "type": "textarea", "label": "What I want my life to hold:"}, {"id": "f1", "type": "textarea", "label": "What I would say to someone I care about:"}, {"id": "f2", "type": "textarea", "label": "A kind step for myself:"}, {"id": "f3", "type": "textarea", "label": "What helps me feel safe doing it:"}, {"id": "f4", "type": "textarea", "label": "Who I can tell:"}]'::jsonb, array['sexual abuse', 'self-compassion', 'values']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('grounding-five-senses-and-boundaries-card', 'Grounding Five Senses and Boundaries Card', 'dbt'::resource_kind, 'A card for grounding with the senses and rehearsing a clear boundary phrase.', 'Use it to help a client ground in the present and practice stating a boundary.', array['Adults', 'Teens']::text[], '25 minutes', 'Practice the senses skill and a short boundary phrase, such as I am not okay with that, in a safe setting. Stay in the present. Offer 988 (call or text) if they feel in crisis.', '[{"id": "f0", "type": "textarea", "label": "What I see around me:"}, {"id": "f1", "type": "textarea", "label": "What I hear:"}, {"id": "f2", "type": "textarea", "label": "What I can touch:"}, {"id": "f3", "type": "textarea", "label": "My boundary phrase:"}, {"id": "f4", "type": "textarea", "label": "Who I can say it to:"}]'::jsonb, array['sexual abuse', 'grounding', 'boundaries']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-and-trusted-adults-page', 'Body Safety Rules and Trusted Adults Page', 'kids'::resource_kind, 'A page where a child draws the grown-ups they can tell and learns body safety rules.', 'Use it to help a child know trusted adults and that they can always tell.', array['Children']::text[], '30 minutes', 'The child draws trusted adults and a safe way to tell. Teach that bodies are private and no secrets about touching. If a child discloses anything, remember your reporting duties and follow them. Parents can practice listening calmly.', '[{"id": "f0", "type": "textarea", "label": "The grown-ups I can tell:"}, {"id": "f1", "type": "textarea", "label": "What I can say if I feel unsafe:"}, {"id": "f2", "type": "textarea", "label": "A rule about my body:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell if something feels wrong:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('personal-coping-menu-starter-page', 'Personal Coping Menu Starter Page', 'worksheet'::resource_kind, 'A menu a client fills out of coping options sorted by time and energy.', 'Use it to help a client build a menu of coping options for different moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Sort options by how much time and energy they take: one minute, ten minutes and long. Pick two from each. Review after a week to see which were used.', '[{"id": "f0", "type": "textarea", "label": "One-minute options:"}, {"id": "f1", "type": "textarea", "label": "Ten-minute options:"}, {"id": "f2", "type": "textarea", "label": "Longer options:"}, {"id": "f3", "type": "textarea", "label": "What I will use when I am low on energy:"}, {"id": "f4", "type": "textarea", "label": "What I will use when I am wound up:"}]'::jsonb, array['coping skills', 'planning', 'self-soothing']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('pocket-card-helpful-thoughts-page', 'Pocket Card Helpful Thoughts Page', 'cbt'::resource_kind, 'A page for writing coping thoughts on small cards for hard moments.', 'Use it to help a client carry helpful thoughts they believe for hard moments.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes a few coping statements that feel believable, not just positive. Test them against a rehearsed hard moment. Revise any that sound false.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I expect:"}, {"id": "f1", "type": "textarea", "label": "A thought that helps:"}, {"id": "f2", "type": "textarea", "label": "Why I believe it:"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card:"}, {"id": "f4", "type": "textarea", "label": "What I will say when I need it:"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('fork-in-the-road-coping-page', 'Fork in the Road Coping Page', 'act'::resource_kind, 'A page for the choice between moving away from or toward in a hard moment.', 'Use it to help a client notice a choice point and pick a move toward what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the choice point and map what the client does when hooked, and what they could do toward their values. Both can be true and neither is bad. Try it in a hard moment and review.', '[{"id": "f0", "type": "textarea", "label": "The hard moment:"}, {"id": "f1", "type": "textarea", "label": "What hooks me:"}, {"id": "f2", "type": "textarea", "label": "What I do to get away:"}, {"id": "f3", "type": "textarea", "label": "What I could do toward what matters:"}, {"id": "f4", "type": "textarea", "label": "What I choose this week:"}]'::jsonb, array['coping skills', 'choice point', 'core ACT']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('four-letter-stop-habit-card', 'Four Letter STOP Habit Card', 'dbt'::resource_kind, 'A card that walks through Stop, Take a step back, Observe and Proceed mindfully.', 'Use it to help a client pause before reacting.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice the steps with a mild trigger in session. Ask the client where they would put a visual reminder. Review how it went when they used it.', '[{"id": "f0", "type": "textarea", "label": "Where I could use STOP:"}, {"id": "f1", "type": "textarea", "label": "What I do when I stop:"}, {"id": "f2", "type": "textarea", "label": "What I notice when I step back:"}, {"id": "f3", "type": "textarea", "label": "What I observe:"}, {"id": "f4", "type": "textarea", "label": "How I proceed:"}]'::jsonb, array['coping skills', 'distress tolerance', 'STOP']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('decorate-a-box-coping-tools-craft', 'Decorate-a-Box Coping Tools Craft', 'kids'::resource_kind, 'A craft where a child decorates a toolbox with drawn coping tools.', 'Use it to help a child collect coping ideas they like and can use.', array['Children']::text[], '30 minutes', 'The child decorates a box and draws or writes tools such as breathing, drawing, a hug and a favorite song. The parent adds one idea and learns how to prompt it. Keep the box where the child can reach it.', '[{"id": "f0", "type": "textarea", "label": "Tools in my toolbox:"}, {"id": "f1", "type": "textarea", "label": "My favorite tool:"}, {"id": "f2", "type": "textarea", "label": "What I use when I am upset:"}, {"id": "f3", "type": "textarea", "label": "Who can help me use it:"}]'::jsonb, array['coping skills', 'children', 'craft']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('rungs-of-courage-fear-ladder-draft', 'Rungs of Courage Fear Ladder Draft', 'worksheet'::resource_kind, 'A page for ranking feared situations from easiest to hardest.', 'Use it to help a client build a fear ladder they can climb one step at a time.', array['Adults', 'Teens']::text[], '30 minutes', 'The client lists feared situations related to one fear and ranks them by difficulty. Choose the first step and plan support. Review the ladder after attempts and add rungs.', '[{"id": "f0", "type": "textarea", "label": "The fear I want to work on:"}, {"id": "f1", "type": "textarea", "label": "Situations from easiest to hardest:"}, {"id": "f2", "type": "textarea", "label": "The first step:"}, {"id": "f3", "type": "textarea", "label": "What I will do to prepare:"}, {"id": "f4", "type": "textarea", "label": "Who will support me:"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('fear-forecast-versus-result-page', 'Fear Forecast Versus Result Page', 'cbt'::resource_kind, 'A page for predicting what will happen when facing a fear and checking afterward.', 'Use it to help a client check fear predictions against what happens.', array['Adults', 'Teens']::text[], '25 minutes', 'Before a step, the client writes what they predict and how strongly they believe it. After, they write what happened. Look at what the outcome says and what to try next.', '[{"id": "f0", "type": "textarea", "label": "The step I will take:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen:"}, {"id": "f2", "type": "textarea", "label": "How sure I am, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What happened:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['phobias', 'predictions', 'exposure']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('fear-and-life-direction-page', 'Fear and Life Direction Page', 'act'::resource_kind, 'A page connecting facing a fear to what the client wants more of in life.', 'Use it to help a client link small steps with a fear to what they value.', array['Adults']::text[], '25 minutes', 'Ask what the fear has kept them from and what they would like to do more of. Pick a small step and agree to bring along the fear. Review how it felt.', '[{"id": "f0", "type": "textarea", "label": "What the fear has kept me from:"}, {"id": "f1", "type": "textarea", "label": "What I want more of:"}, {"id": "f2", "type": "textarea", "label": "A step I could take:"}, {"id": "f3", "type": "textarea", "label": "The feeling I will bring:"}, {"id": "f4", "type": "textarea", "label": "What I did:"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('treasure-hunt-path-to-my-fear-map', 'Treasure Hunt Path to My Fear Map', 'kids'::resource_kind, 'A drawn map where a child plots small brave steps toward a fear.', 'Use it to help a child approach a fear step by step in a playful way.', array['Children']::text[], '30 minutes', 'The child draws a map with a stop for each step, easiest first. The parent offers to go along and not push. Cheer for trying and revisit after each step.', '[{"id": "f0", "type": "textarea", "label": "What I am scared of:"}, {"id": "f1", "type": "textarea", "label": "The first stop on my map:"}, {"id": "f2", "type": "textarea", "label": "The next stop:"}, {"id": "f3", "type": "textarea", "label": "The treasure at the end:"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('roll-and-face-it-small-steps-game', 'Roll and Face It Small Steps Game', 'game'::resource_kind, 'A dice game where rolls decide small, agreed steps near a fear.', 'Use it to help clients take small playful steps near a fear with company.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Agree on a list of mild tasks ahead and let a die choose among them. Players share what they felt and what happened. Debrief on what they would repeat, and let them pass.', '[{"id": "f0", "type": "textarea", "label": "The task I rolled:"}, {"id": "f1", "type": "textarea", "label": "How scared I was, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "What I will repeat this week:"}]'::jsonb, array['phobias', 'exposure', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('thank-you-body-appreciation-page', 'Thank You Body Appreciation Page', 'worksheet'::resource_kind, 'A page for naming what a client''s body lets them do and feel.', 'Use it to help a client notice what their body does for them.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to list what their body lets them do, feel and share. Avoid any talk of size, shape or looks. Choose one thing to thank the body for each day this week.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do:"}, {"id": "f1", "type": "textarea", "label": "Things it helps me feel:"}, {"id": "f2", "type": "textarea", "label": "A moment it carried me through:"}, {"id": "f3", "type": "textarea", "label": "A thank you to my body:"}, {"id": "f4", "type": "textarea", "label": "What I will notice this week:"}]'::jsonb, array['body image', 'appreciation', 'self-compassion']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('mirror-words-tone-check-page', 'Mirror Words Tone Check Page', 'cbt'::resource_kind, 'A page for catching critical thoughts at the mirror and writing neutral ones.', 'Use it to help a client notice critical thoughts and try neutral ones.', array['Adults', 'Teens']::text[], '25 minutes', 'The client records what they say to themselves at the mirror, how it feels and a neutral or respectful alternative. Focus on tone of the thought, not on how the body looks. Review which alternatives felt believable.', '[{"id": "f0", "type": "textarea", "label": "What I told myself:"}, {"id": "f1", "type": "textarea", "label": "How I felt:"}, {"id": "f2", "type": "textarea", "label": "A neutral thought I could use:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f4", "type": "textarea", "label": "How I feel now:"}]'::jsonb, array['body image', 'self-talk', 'cognitive restructuring']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('what-matters-more-than-looks-page', 'What Matters More Than Looks Page', 'act'::resource_kind, 'A page for choosing what matters more than appearance and acting on it.', 'Use it to help a client act on what matters rather than appearance.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client wants their life to be about and what they have held back on because of how they felt about their body. Choose a small step toward it with the feelings along.', '[{"id": "f0", "type": "textarea", "label": "What I want my life to be about:"}, {"id": "f1", "type": "textarea", "label": "What I have held back from:"}, {"id": "f2", "type": "textarea", "label": "What I would do if looks mattered less:"}, {"id": "f3", "type": "textarea", "label": "A step I will take:"}, {"id": "f4", "type": "textarea", "label": "What I notice when I do it:"}]'::jsonb, array['body image', 'values', 'willingness']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('beyond-looks-appreciation-exchange', 'Beyond Looks Appreciation Exchange', 'couples'::resource_kind, 'A page for partners to share what they value in each other beyond looks.', 'Use it to help partners say what they value about each other beyond appearance.', array['Couples']::text[], '30 minutes', 'Each partner writes what they value about the other, such as humor, effort or kindness, and reads it aloud. Notice how it feels to receive. Avoid comments on the body.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What I value in you:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I value in you:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear it:"}, {"id": "f3", "type": "textarea", "label": "A way we will say more:"}]'::jsonb, array['body image', 'appreciation', 'couples']::text[], '2026-11-07T15:00:00+00:00'::timestamptz),
  ('what-my-body-does-charades-game', 'What My Body Does Charades Game', 'game'::resource_kind, 'A group charades game where players act out things their bodies do for them.', 'Use it to help a group celebrate what bodies do rather than how they look.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Players act out a movement or activity they enjoy and others guess. Debrief on what bodies make possible. Keep comments off appearance and steer back if they slip.', '[{"id": "f0", "type": "textarea", "label": "The action I acted out:"}, {"id": "f1", "type": "textarea", "label": "Why I like it:"}, {"id": "f2", "type": "textarea", "label": "What my body helped me do:"}, {"id": "f3", "type": "textarea", "label": "What I will do this week:"}]'::jsonb, array['body image', 'group', 'game']::text[], '2026-11-07T15:00:00+00:00'::timestamptz)
